// ═══════════════════════════════════════════════════════════
// CONFIGURATION
//
// ZUORDNUNG states which machine produces which part, and which openLCA
// parameter the measured energy acts on. It is the only place that has to
// be touched when the production sequence changes.
//
//   aas       = identifier of the part shell (formed from its name)
//   prozess   = openLCA process of the part
//   parameter = energy parameter of that process
//
// Machines without an entry are skipped and named. Baxter and Montrac
// belong to the assembly; their energy currently comes from the simulation
// and is deliberately not recorded twice here.
// ═══════════════════════════════════════════════════════════
const BASIS = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';

// Which part is currently on the lathe: 'Bolzen' or 'Huelse'.
const DREHTEIL = String(env.get('SDI_OPCUA_TURNED_PART') || 'Bolzen')
    .trim().toLowerCase();

const BOLZEN = { aas: BASIS + '/Bolzen_Aluminium',
                 prozess: '90291baa-d449-4afc-9d2a-01e8e650afd8',
                 parameter: 'Energieverbrauch_Bolzen' };
const HUELSE = { aas: BASIS + '/Huelse_Aluminium',
                 prozess: '57c37380-e320-4712-b605-48dca9472829',
                 parameter: 'Energieverbrauch_Huelse' };

const ZUORDNUNG = {
    // One machine, two parts: the lathe produces the first step of the bolt
    // and the sleeve. Which of them is running cannot be known by a fixed
    // entry - it is held in SDI_OPCUA_TURNED_PART and is the only value that
    // changes from order to order.
    //
    // If the measurement carries the part name in its idShort, both can sit
    // side by side - otherwise the newer measurement replaces the older one
    // and a part silently loses its manufacturing energy.
    Drehprozess_Bolzen: BOLZEN,
    Drehprozess_Huelse: HUELSE,
    // Without the name suffix the configuration decides, as before.
    Drehprozess:  DREHTEIL.indexOf('h') === 0 ? HUELSE : BOLZEN,
    // The mill does the second step of the bolt - the bore and the thread.
    // Its energy is added to the turning energy of the same bolt; both
    // entries sit side by side in the shell and are summed onto the same
    // parameter in the calculation.
    Fraesprozess: BOLZEN,
    'Drucker3D':  { aas: BASIS + '/Stiftspitze_Helix_PLA',
                    prozess: '5043f2ab-9463-470d-888e-1855c805b042',
                    parameter: 'Energieverbrauch_Stiftspitze' }
};

const cfg = {
    aasUrl:      env.get('SDI_AAS_URL') || 'http://localhost:8081',
    opcuaId:     env.get('SDI_OPCUA_SUBMODEL_ID')
                 || 'localhost/demo/SubmodelTemplate/SAL-OPC-UA-Daten',
    zuordnung:   ZUORDNUNG
};
flow.set('cfg', cfg);

const b64 = Buffer.from(cfg.opcuaId, 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

msg.method = 'GET';
msg.url = cfg.aasUrl + '/submodels/' + b64;
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
node.status({ fill: 'blue', shape: 'dot', text: 'reading machine data' });
return msg;

// ═══════════════════════════════════════════════════════════
// Evaluate the measurements and form the energy per piece.
//
//   energy [MJ] = average power [W] x process duration [s] / 1,000,000 / pieces
//
// The machine entries are searched for rather than addressed by fixed
// positions - the layout of the OPC UA submodel may change.
// ═══════════════════════════════════════════════════════════
const cfg = flow.get('cfg');
const sm = msg.payload;
if (!sm || !Array.isArray(sm.submodelElements)) {
    node.error('The submodel holding the machine data could not be read', msg);
    return null;
}

function propValue(coll, id) {
    const p = (coll.value || []).find(e => e && e.idShort === id);
    return p ? p.value : null;
}
function zahl(v) {
    const n = parseFloat(v);
    return isNaN(n) ? null : n;
}

// Collect every collection that carries a power reading
const maschinen = [];
(function suche(elemente) {
    (elemente || []).forEach(e => {
        if (!e) { return; }
        if (e.modelType === 'SubmodelElementCollection') {
            const leistung = propValue(e, 'AveragePower') !== null
                ? propValue(e, 'AveragePower') : propValue(e, 'Leistung');
            if (leistung !== null) { maschinen.push(e); return; }
        }
        if (Array.isArray(e.value)) { suche(e.value); }
    });
})(sm.submodelElements);

if (maschinen.length === 0) {
    node.error('No machine with a power reading found', msg);
    return null;
}

const auftraege = {};
const ohneZuordnung = [];
const ohneWerte = [];

maschinen.forEach(m => {
    const name = m.idShort;
    const z = cfg.zuordnung[name];
    if (!z) { ohneZuordnung.push(name); return; }

    const leistung = zahl(propValue(m, 'AveragePower')) ?? zahl(propValue(m, 'Leistung'));
    const dauer = zahl(propValue(m, 'ProcessDuration'));
    const stueck = zahl(propValue(m, 'PieceCount')) || 1;

    if (leistung === null || dauer === null || !(leistung > 0) || !(dauer > 0)) {
        ohneWerte.push(name);
        return;
    }

    const energieMJ = leistung * dauer / 1e6 / stueck;
    const eintrag = {
        machine: name,
        averagePowerW: leistung,
        processDurationS: dauer,
        pieceCount: stueck,
        energyPerUnitMJ: energieMJ,
        start: propValue(m, 'TimeManufacturingStart'),
        ende: propValue(m, 'TimeManufacturingEnd'),
        serverIP: propValue(m, 'ServerIP'),
        lcaProcessId: z.prozess,
        lcaParameterName: z.parameter
    };
    if (!auftraege[z.aas]) { auftraege[z.aas] = []; }
    auftraege[z.aas].push(eintrag);
});

if (ohneZuordnung.length > 0) {
    node.log('Without a part assignment (skipped): ' + ohneZuordnung.join(', '));
}
if (ohneWerte.length > 0) {
    node.warn('Without usable measurements: ' + ohneWerte.join(', '));
}

const liste = Object.keys(auftraege).map(aas => ({ aas: aas, eintraege: auftraege[aas] }));
if (liste.length === 0) {
    node.error('No machine delivers usable data', msg);
    return null;
}

flow.set('auftraege', liste);
flow.set('index', 0);
flow.set('geschrieben', []);
node.log(maschinen.length + ' machines read, ' + liste.length + ' part shells to update');
return msg;

// Take the next part shell off the queue
const cfg = flow.get('cfg');
const liste = flow.get('auftraege') || [];
const i = flow.get('index') || 0;

if (i >= liste.length) {
    // done - report the result
    msg.payload = {
        status: 'ok',
        dataSource: 'Manufacturing',
        aktualisiert: flow.get('geschrieben') || []
    };
    node.status({ fill: 'green', shape: 'dot',
                  text: (flow.get('geschrieben') || []).length + ' part shells' });
    return [null, msg];
}

const auftrag = liste[i];
flow.set('aktuell', auftrag);

const id = auftrag.aas + '/DataSources';
const b64 = Buffer.from(id, 'utf8').toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
flow.set('aktuellB64', b64);

msg.method = 'GET';
msg.url = cfg.aasUrl + '/submodels/' + b64;
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
node.status({ fill: 'blue', shape: 'dot',
              text: (i + 1) + '/' + liste.length + ' ' + auftrag.aas.split('/').pop() });
return [msg, null];

// ═══════════════════════════════════════════════════════════
// MAPPING machine data -> part shell
// Target: DataSources -> SML "DataSources" -> SMC "Manufacturing"
//         -> SML "ManufacturingProcesses"
// ═══════════════════════════════════════════════════════════
const auftrag = flow.get('aktuell');
const sm = msg.payload;

if (!sm || !Array.isArray(sm.submodelElements)) {
    node.error('DataSources of the part shell cannot be read: ' + auftrag.aas, msg);
    return null;
}

function idShort(str) {
    let s = String(str || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_').replace(/__+/g, '_').replace(/_+$/, '');
    if (!/^[a-zA-Z]/.test(s)) { s = 'M_' + s; }
    return s.substring(0, 128) || 'Undefined';
}
const prop = (id, v, t) => ({ modelType: 'Property', idShort: id,
    valueType: t || 'xs:string', value: v === null || v === undefined ? '' : String(v) });
const smc = (id, v) => ({ modelType: 'SubmodelElementCollection', idShort: id, value: v });
const byId = (arr, id) => (arr || []).find(e => e && e.idShort === id);

// The serial numbers of the pieces produced in this run.
//
// They are assigned by article number and order: the numbers given out last
// belong to the most recent run. That is not booked - for that the shop
// floor would have to report back which piece ran on which machine. The
// origin of the assignment therefore stands beside it rather than being
// passed over in silence.
const artikelNr = flow.get('artikelNr') || '';
// The booked assembly first, then the order in which numbers were given out.
const gebucht = flow.get('montageSerien');
const alleSerien = (gebucht && gebucht[artikelNr])
    || (flow.get('serienNachArtikel') || {})[artikelNr] || [];
const stueckzahl = Math.max(1, Number(auftrag.eintraege[0]
    && auftrag.eintraege[0].pieceCount) || 1);
const serien = alleSerien.slice(0, stueckzahl);
const auftragsNr = flow.get('fertigungsauftrag') || '';

const PROZESS_NAMEN = {
    Fraesprozess: 'Milling',
    Drehprozess: 'Turning',
    Drehprozess_Bolzen: 'TurningBolt',
    Drehprozess_Huelse: 'TurningSleeve',
    Drucker3D: 'Printing3D'
};
function prozessName(m) { return PROZESS_NAMEN[m] || m; }

// The idShort is the RunId: otherwise two measurements of the same machine
// would carry the same name.
function laufKennung(e) {
    return idShort(prozessName(e.machine)) + '_'
         + String(e.start || '').split('-').join('')
               .split(':').join('').substring(0, 15);
}
const prozesse = auftrag.eintraege.map(e => smc(laufKennung(e), [
    prop('Process', prozessName(e.machine)),
    prop('MachineName', e.machine),
    prop('AveragePower', e.averagePowerW, 'xs:double'),
    prop('AveragePowerUnit', 'W'),
    prop('ProcessDuration', e.processDurationS, 'xs:double'),
    prop('ProcessDurationUnit', 's'),
    prop('PieceCount', e.pieceCount, 'xs:double'),
    prop('EnergyPerUnit', e.energyPerUnitMJ, 'xs:double'),
    prop('EnergyPerUnitUnit', 'MJ'),
    prop('ServerIP', e.serverIP),
    prop('LCAProcessId', e.lcaProcessId),
    prop('LCAParameterName', e.lcaParameterName),
    // A run only becomes evidence once it names a piece.
    prop('RunId', laufKennung(e)),
    // Every run carries its own time. When it stood on the container only,
    // every machine of a part showed the same end time - for the bolt, the
    // milling therefore showed the time of the turning.
    ...(e.start ? [prop('TimeManufacturingStart', e.start, 'xs:dateTime')] : []),
    ...(e.ende ? [prop('TimeManufacturingEnd', e.ende, 'xs:dateTime')] : []),
    prop('ManufacturingOrder', auftragsNr),
    prop('SerialNumbers', serien.join(' ')),
    prop('SerialNumberSource', serien.length
        ? (gebucht && gebucht[artikelNr]
            ? 'booked assembly ' + (flow.get('montageStueck') || '')
              + ' in Odoo (stock move line)'
            : 'Odoo stock.lot, assigned by article and order of '
              + 'production, not booked against a manufacturing order')
        : 'no serial number available'),
    // With more than one piece per run the energy per piece is an average -
    // that belongs written alongside, otherwise it reads as a measurement
    // taken on the single piece.
    prop('EnergyAllocation', Number(e.pieceCount) > 1
        ? 'average over ' + e.pieceCount + ' pieces of one run'
        : 'single piece')
]));

const start = auftrag.eintraege.map(e => e.start).filter(Boolean).sort()[0] || '';
const ende = auftrag.eintraege.map(e => e.ende).filter(Boolean).sort().pop() || '';
const summe = auftrag.eintraege.reduce((s, e) => s + e.energyPerUnitMJ, 0);


// Collect the runs already in the shell and merge them over the RunId: the
// same run replaces itself, a new one is added, and every other one stays.
const dsListe = byId(sm.submodelElements, 'DataSources');
const mdAlt = byId((dsListe || {}).value, 'MachineData')
           || byId((dsListe || {}).value, 'Manufacturing');
const plAlt = byId((mdAlt || {}).value, 'ManufacturingProcesses');
const alteLaeufe = (plAlt && plAlt.value) ? plAlt.value.slice() : [];
function kennung(k) {
    const r = ((k || {}).value || []).find(y => y.idShort === 'RunId');
    return r ? String(r.value) : ((k || {}).idShort || '');
}
const neueKennungen = prozesse.map(kennung);
const zusammen = alteLaeufe
    .filter(k => neueKennungen.indexOf(kennung(k)) < 0)
    .concat(prozesse);

const mfgValue = [
    prop('DataSource', 'MachineData'),
    prop('SourceSystem', 'OPC UA'),
    prop('TimeOfRetrieval', new Date().toISOString(), 'xs:dateTime'),
    // Only write a timestamp when the machine delivers one. An empty entry
    // typed xs:dateTime is invalid under the specification and is reported
    // when the package is checked.
    ...(start ? [prop('TimeManufacturingStart', start, 'xs:dateTime')] : []),
    ...(ende ? [prop('TimeManufacturingEnd', ende, 'xs:dateTime')] : []),
    prop('TotalEnergyPerUnit', summe, 'xs:double'),
    prop('TotalEnergyPerUnitUnit', 'MJ'),
    smc('ManufacturingProcesses', zusammen)
];

let list = byId(sm.submodelElements, 'DataSources')
        || byId(sm.submodelElements, 'Data Sources')
        || sm.submodelElements.find(e => e.modelType === 'SubmodelElementList');
if (!list) {
    node.error('SubmodelElementList "DataSources" not found in ' + auftrag.aas, msg);
    return null;
}
if (!Array.isArray(list.value)) { list.value = []; }

const pos = list.value.findIndex(e => e && e.idShort === 'MachineData');
const neu = smc('MachineData', mfgValue);
if (pos >= 0) { list.value[pos] = neu; } else { list.value.push(neu); }

const geschrieben = flow.get('geschrieben') || [];
geschrieben.push({ aas: auftrag.aas.split('/').pop(),
                   maschinen: auftrag.eintraege.map(e => e.machine),
                   energieMJ: summe });
flow.set('geschrieben', geschrieben);

msg.method = 'PUT';
msg.url = flow.get('cfg').aasUrl + '/submodels/' + flow.get('aktuellB64');
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = sm;
return msg;

// Check the write and move on to the next part shell
const auftrag = flow.get('aktuell');
if (msg.statusCode && msg.statusCode >= 400) {
    node.error('Write failed for ' + auftrag.aas + ': HTTP ' + msg.statusCode, msg);
    return null;
}
node.log('Machine data written: ' + auftrag.aas.split('/').pop());
flow.set('index', (flow.get('index') || 0) + 1);
msg.payload = '';
return msg;

// Log in to Odoo in order to fetch the serial numbers.
//
// Without Odoo the flow still runs through: the serial number is then
// missing, and the shell says so. A measurement without a number is worth
// less, but it is better than no measurement.
const cfg = {
    url: env.get('SDI_ODOO_URL') || '',
    db: env.get('SDI_ODOO_DB') || '',
    user: env.get('SDI_ODOO_USER') || '',
    key: env.get('SDI_ODOO_APIKEY') || ''
};
flow.set('odoo', cfg);
if (!cfg.key || !cfg.url) {
    node.warn('No Odoo access - machine data is written without a serial '
            + 'number.');
    return [null, msg];
}
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'common', method: 'login', args: [cfg.db, cfg.user, cfg.key] } };
return [msg, null];

// Fetches the articles with their reference.
const cfg = flow.get('odoo');
const uid = (msg.payload || {}).result;
if (!uid) {
    node.warn('Odoo login failed - carrying on without serial numbers.');
    return [null, { topic: 'weiter' }];
}
flow.set('odooUid', uid);
msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'product.product', 'search_read',
           [[]], { fields: ['default_code'], limit: 100 }] } };
return [msg, null];

// Fetches the serial numbers and the open manufacturing order.
const cfg = flow.get('odoo');
const uid = flow.get('odooUid');
if ((msg.payload || {}).error) {
    node.warn('Odoo reports: ' + ((msg.payload.error.data) || {}).message);
    return [null, { topic: 'weiter' }];
}
const artikelNachId = {};
for (const v of ((msg.payload || {}).result || [])) {
    artikelNachId[v.id] = v.default_code;
}
flow.set('artikelNachId', artikelNachId);

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'stock.lot', 'search_read',
           [[]], { fields: ['name', 'product_id', 'create_date'],
                   order: 'create_date desc', limit: 200 }] } };
return [msg, null];

// Assigns the numbers to the articles and fetches the manufacturing order.
const cfg = flow.get('odoo');
const uid = flow.get('odooUid');
if ((msg.payload || {}).error) {
    node.warn('Odoo reports: ' + ((msg.payload.error.data) || {}).message);
    return [null, { topic: 'weiter' }];
}
const artikelNachId = flow.get('artikelNachId') || {};
const nachArtikel = {};
for (const l of ((msg.payload || {}).result || [])) {
    const a = artikelNachId[(l.product_id || [])[0]];
    if (!a) { continue; }
    if (!nachArtikel[a]) { nachArtikel[a] = []; }
    nachArtikel[a].push(l.name);
}
flow.set('serienNachArtikel', nachArtikel);
node.log('Serial numbers per article: ' + JSON.stringify(nachArtikel));

msg.url = cfg.url + '/jsonrpc';
msg.method = 'POST';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', method: 'call', params: {
    service: 'object', method: 'execute_kw',
    args: [cfg.db, uid, cfg.key, 'mrp.production', 'search_read',
           [[['state', 'in', ['confirmed', 'progress', 'to_close', 'done']]]],
           { fields: ['name', 'product_qty'], limit: 1 }] } };
return msg;

// Keeps the order and fetches the booked assembly.
if (!(msg.payload || {}).error) {
    const a = ((msg.payload || {}).result || [])[0];
    if (a) {
        flow.set('fertigungsauftrag', a.name);
        node.log('Manufacturing order: ' + a.name);
    }
}
// Which pieces were installed last is held in the shell of the assembled
// product. That assignment is booked - "the newest number per article" is not.
const cfg = flow.get('odoo') || {};
const aas = env.get('SDI_AAS_URL') || 'http://localhost:8081';
const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const produkt = env.get('SDI_LCA_PRODUCT') || 'Kugelschreiber_TracePEN';
function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .split('+').join('-').split('/').join('_').split('=').join('');
}
msg.url = aas + '/submodels/' + b64(basis + '/' + produkt + '/DataSources');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return [msg, null];

// Holds on to the article number and then reads the data sources.
const cfg = { aas: env.get('SDI_AAS_URL') || 'http://localhost:8081',
              basis: env.get('SDI_AAS_BASE') || 'localhost/demo/aas' };
const auftrag = flow.get('aktuell');
const sm = msg.payload;
let artikel = '';
if (sm && Array.isArray(sm.submodelElements)) {
    const e = sm.submodelElements.find(function (x) {
        return x.idShort === 'ProductArticleNumberOfManufacturer';
    });
    artikel = e ? String(e.value || '') : '';
}
if (!artikel) {
    node.warn('No article number in the nameplate of ' + auftrag.aas);
}
flow.set('artikelNr', artikel);

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .split('+').join('-').split('/').join('_').split('=').join('');
}
const kennung = String(auftrag.aas).indexOf('/') >= 0
    ? auftrag.aas : (cfg.basis + '/' + auftrag.aas);
msg.url = cfg.aas + '/submodels/' + b64(kennung + '/DataSources');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Reads the nameplate of the part in order to learn its article number.
//
// The article number is not in the name of the shell, and it should not be
// guessed from it either. It is in the nameplate - that is where it is kept.
const cfg = { aas: env.get('SDI_AAS_URL') || 'http://localhost:8081',
              basis: env.get('SDI_AAS_BASE') || 'localhost/demo/aas' };
const auftrag = flow.get('aktuell');
function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .split('+').join('-').split('/').join('_').split('=').join('');
}
// auftrag.aas already carries the full identifier. Putting the base in
// front of it once more produces a path that does not exist - and the
// article number stays empty without anything reporting an error.
const kennung = String(auftrag.aas).indexOf('/') >= 0
    ? auftrag.aas : (cfg.basis + '/' + auftrag.aas);
msg.url = cfg.aas + '/submodels/' + b64(kennung + '/Nameplate');
msg.method = 'GET';
msg.headers = { 'Accept': 'application/json' };
msg.payload = '';
return msg;

// Takes the numbers from the most recent booked assembly.
//
// Without a booking the assignment by article and order stands - with one,
// what is booked counts. Otherwise the measurement hangs off a piece that
// sits in no assembled product, and the instance view stays empty.
const sm = msg.payload;
function finde(sammlung, name) {
    return ((sammlung || {}).value || []).find(function (e) {
        return e && e.idShort === name;
    });
}
function wert(sammlung, name) {
    const e = finde(sammlung, name);
    return e ? e.value : null;
}
let liste = null;
for (const e of ((sm || {}).submodelElements || [])) {
    if (e.idShort === 'DataSources') { liste = e; }
}
const erp = finde(liste, 'ERP') || finde(liste, 'ERPData');
const sammlung = finde(erp, 'AssemblyRecords');
const eintraege = sammlung ? (sammlung.value || []) : [];
if (eintraege.length) {
    const juengste = eintraege.slice().sort(function (a, b) {
        return String(wert(b, 'TimeOfBooking')).localeCompare(
               String(wert(a, 'TimeOfBooking')));
    })[0];
    const teile = (finde(juengste, 'InstalledComponents') || {}).value || [];
    const nachArtikel = {};
    for (const k of teile) {
        const art = wert(k, 'ArticleNumber');
        const nr = wert(k, 'SerialNumber');
        if (art && nr) { nachArtikel[art] = [nr]; }
    }
    flow.set('montageSerien', nachArtikel);
    flow.set('montageStueck', wert(juengste, 'SerialNumber') || '');
    node.log('Booked assembly ' + flow.get('montageStueck') + ': '
           + JSON.stringify(nachArtikel));
} else {
    flow.set('montageSerien', null);
}
return { topic: 'weiter' };
